import assert from 'node:assert/strict';
import { mergeConfig } from '../src/config.js';

function freezeTree(value) {
  if (value && typeof value === 'object') {
    for (const key of Reflect.ownKeys(value)) freezeTree(value[key]);
    Object.freeze(value);
  }
  return value;
}

if (process.argv[2] === 'nested') {
  assert.deepEqual(mergeConfig({ server: { host: 'localhost', port: 8080 } }, { server: { port: 9090 } }), { server: { host: 'localhost', port: 9090 } });
  const defaults = freezeTree({
    server: { host: 'localhost', tls: { enabled: true, cert: { path: 'old', mode: 420 } }, ports: [80, 443] },
    logging: { level: 'info', format: { timestamp: true, color: false } },
    keep: { x: 1 }
  });
  const overrides = freezeTree({
    server: { tls: { cert: { path: 'new' }, ca: 'ca.pem' }, ports: [8443] },
    logging: { format: { color: true } },
    added: { deep: { flag: true } }
  });
  const beforeDefaults = structuredClone(defaults);
  const beforeOverrides = structuredClone(overrides);
  assert.deepEqual(mergeConfig(defaults, overrides), {
    server: { host: 'localhost', tls: { enabled: true, cert: { path: 'new', mode: 420 }, ca: 'ca.pem' }, ports: [8443] },
    logging: { level: 'info', format: { timestamp: true, color: true } },
    keep: { x: 1 }, added: { deep: { flag: true } }
  });
  assert.deepEqual(defaults, beforeDefaults);
  assert.deepEqual(overrides, beforeOverrides);
  assert.deepEqual(mergeConfig({ a: { b: { c: 1 } } }, { a: {} }), { a: { b: { c: 1 } } });
  assert.deepEqual(mergeConfig({ a: { b: { c: 1, d: 2 } } }, { a: { b: { c: undefined } } }), { a: { b: { c: undefined, d: 2 } } });
  for (const replacement of [null, undefined, false, 0, '', 'text', [3, 4]]) {
    assert.deepEqual(mergeConfig({ a: { keep: 1, b: { old: true } } }, { a: { b: replacement } }), { a: { keep: 1, b: replacement } });
  }
  // Depth is not limited to the few levels illustrated above.
  let d = { retained: 1, changed: 0 }, o = { changed: 2 }, expected = { retained: 1, changed: 2 };
  for (let i = 0; i < 40; i++) { d = { child: d, sibling: i }; o = { child: o }; expected = { child: expected, sibling: i }; }
  assert.deepEqual(mergeConfig(d, o), expected);
  // Objects with null prototypes are plain dictionaries too.
  const left = Object.assign(Object.create(null), { keep: 1, change: 2 });
  const right = Object.assign(Object.create(null), { change: 3, add: 4 });
  const merged = mergeConfig({ dict: left }, { dict: right });
  assert.deepEqual(Object.keys(merged.dict).sort(), ['add', 'change', 'keep']);
  assert.equal(merged.dict.keep, 1); assert.equal(merged.dict.change, 3); assert.equal(merged.dict.add, 4);
} else if (process.argv[2] === 'regression') {
  assert.deepEqual(mergeConfig({ level: 'info', color: true }, { level: 'debug', file: 'app.log' }), { level: 'debug', color: true, file: 'app.log' });
  assert.deepEqual(mergeConfig({}, {}), {});
  class Custom { constructor() { this.value = 7; } }
  for (const replacement of [[{ x: 3 }], [], null, undefined, 's', '', 0, 9, false, new Date(0), /x/, new Custom()]) {
    const defaults = freezeTree({ value: { old: 1 }, untouched: { deep: [1, 2] } });
    const overrides = Object.freeze({ value: replacement });
    const result = mergeConfig(defaults, overrides);
    assert.deepEqual(result, { value: replacement, untouched: { deep: [1, 2] } });
    assert.equal(result.value, replacement);
    assert.notEqual(result, defaults); assert.notEqual(result, overrides);
    assert.deepEqual(defaults, { value: { old: 1 }, untouched: { deep: [1, 2] } });
    assert.equal(overrides.value, replacement);
  }
  for (const old of [null, undefined, 'text', 5, false, [1, 2], new Date(0), new Custom()]) {
    assert.deepEqual(mergeConfig({ value: old }, { value: { fresh: 3 } }), { value: { fresh: 3 } });
  }
  const symbol = Symbol('config');
  const defaults = { [symbol]: 1, keep: true };
  const overrides = { [symbol]: 2 };
  Object.defineProperty(overrides, 'hidden', { value: 3 });
  assert.deepEqual(mergeConfig(defaults, overrides), { [symbol]: 2, keep: true });
  const result = mergeConfig(defaults, {});
  assert.notEqual(result, defaults);
} else {
  throw new Error('Specify nested or regression');
}
